text:
/* Semantic roles. Components never select a light/dark color themselves. */
:root, :root[data-theme="dark"] {
  color-scheme: dark;
  --treemap-hover-border: #60a5fa;
  --treemap-loc-low: hsl(217 35% clamp(4%, calc(20% + var(--treemap-shade-shift)), 98%));
  --treemap-loc-high: hsl(217 95% clamp(4%, calc(72% + var(--treemap-shade-shift)), 98%));
  --surface-app: var(--neutral-950);
  --surface-panel: #101419;
  --surface-raised: #141920;
  --surface-inset: #0b0e12;
  --surface-control: #1b222b;
  --surface-hover: #263343;
  --surface-selected: #293f4b;
  --surface-canvas: #0d1014;
  --surface-code: #1e1e1e;
  --surface-code-gutter: #181818;
  --diagram-syntax-type: #4ec9b0;
  --diagram-syntax-function: #dcdcaa;
  --diagram-syntax-variable: #9cdcfe;
  --diagram-syntax-keyword: #c586c0;
  --diagram-syntax-string: #ce9178;
  --diagram-syntax-number: #b5cea8;
  --diagram-syntax-reference: #c4a7ef;
  --diagram-syntax-structure: #939dab;
  --surface-backdrop: #05070ab8;
  /* Codex terminal markdown: neutral foreground, ChatGPT blue, Catppuccin raw-code green. */
  --agent-transcript-text: #d4d4d4;
  --agent-markdown-accent: #63a8f8;
  --agent-markdown-code: #a6e3a1;
  --agent-markdown-quote: #a6e3a1;
  --text-primary: #d8dee9;
  --text-secondary: #b7bfca;
  --text-muted: #939dab;
  --text-disabled: #50535a;
  --text-on-accent: #edf4ff;
  --border-default: #4c566a;
  --border-subtle: #27303a;
  --border-strong: #628eab;
  --accent-primary: #88c0d0;
  --accent-primary-hover: #8fbcbb;
  --accent-success: #a3be8c;
  --accent-warning: #ebcb8b;
  --accent-danger: #bf616a;
  --accent-info: #8bc8ff;
  --accent-secondary: #b48ead;
  --action-fill: #285d83;
  --action-border: #2f6b96;
  --change-added: #76c99b;
  --change-deleted: #f0a35a;
  --change-mixed: #b9c8d6;
  --diff-added-fill: #244832;
  --diff-added-text: #c1f0bb;
  --diff-added-border: #45865d;
  --diff-deleted-fill: #532c35;
  --diff-deleted-text: #ffc1c6;
  --diff-deleted-border: #a45264;
  --diff-modified-fill: #51401e;
  --diff-modified-text: #ffe2a0;
  --diff-hunk-added-fill: #142c23;
  --diff-hunk-deleted-fill: #321d25;
  --migration-source-fill: #20364d;
  --migration-source-text: #d5e6fa;
  --migration-source-border: #7da7d9;
  --migration-target-fill: #173f70;
  --migration-target-text: #e1f0ff;
  --migration-target-border: #66b3ff;
  --selection-fill: #24415b;
  --selection-text: #d7edff;
  --selection-border: #507a9f;
  --attention-color: #ffd27a;
  --surface-visualization: #0c1a28;
  --surface-blueprint: #0a1622;
  --text-visualization: #d6e4f0;
  --text-visualization-muted: #91afc5;
  --text-visualization-heading: #8fbfdf;
  --border-visualization: #2e5574;
  --grid-canvas: rgb(136 192 208 / 3%);
  --grid-visualization: #6f98b817;
  --shadow-color: #000;
  --shadow-panel: 0 12px 32px #0004;
  --shadow-popup: 0 4px 16px #0008;
}
:root[data-theme="light"] {
  color-scheme: light;
  --treemap-hover-border: #2563eb;
  --treemap-loc-low: hsl(217 70% clamp(4%, calc(94% + var(--treemap-shade-shift)), 98%));
  --treemap-loc-high: hsl(217 90% clamp(4%, calc(55% + var(--treemap-shade-shift)), 98%));
  --surface-app: var(--neutral-100);
  --surface-panel: var(--neutral-50);
  --surface-raised: var(--neutral-0);
  --surface-inset: #eef0f3;
  --surface-control: #f0f2f5;
  --surface-hover: #e4e9ef;
  --surface-selected: #dcecf3;
  --surface-canvas: var(--neutral-0);
  --surface-code: var(--neutral-0);
  --surface-code-gutter: #f2f3f5;
  --diagram-syntax-type: #176b60;
  --diagram-syntax-function: #795e00;
  --diagram-syntax-variable: #175b91;
  --diagram-syntax-keyword: #80388c;
  --diagram-syntax-string: #9b4528;
  --diagram-syntax-number: #356a30;
  --diagram-syntax-reference: #7046a3;
  --diagram-syntax-structure: #687382;
  --surface-backdrop: #20242b55;
  --agent-transcript-text: #333333;
  --agent-markdown-accent: #1c64c8;
  /* Darken Latte green for readable small text on the light panel. */
  --agent-markdown-code: #2f7d20;
  --agent-markdown-quote: #2f7d20;
  --text-primary: var(--neutral-900);
  --text-secondary: var(--neutral-700);
  --text-muted: #596575;
  --text-disabled: #78818e;
  --text-on-accent: var(--neutral-0);
  --border-default: #b5beca;
  --border-subtle: #dce1e7;
  --border-strong: #6e849a;
  --accent-primary: #17667f;
  --accent-primary-hover: #115067;
  --accent-success: #326d2c;
  --accent-warning: #805700;
  --accent-danger: #a32a38;
  --accent-info: #245faa;
  --accent-secondary: #82518a;
  --action-fill: #28678f;
  --action-border: #20577b;
  --change-added: #287d51;
  --change-deleted: #a75618;
  --change-mixed: #67798b;
  --diff-added-fill: #dceedd;
  --diff-added-text: #24572d;
  --diff-added-border: #4c8d5d;
  --diff-deleted-fill: #fae3e5;
  --diff-deleted-text: #8c2935;
  --diff-deleted-border: #b75361;
  --diff-modified-fill: #fff0c7;
  --diff-modified-text: #704e00;
  --diff-hunk-added-fill: #e7f4e9;
  --diff-hunk-deleted-fill: #fcecef;
  --migration-source-fill: #e3ebf7;
  --migration-source-text: #2d527e;
  --migration-source-border: #507bac;
  --migration-target-fill: #dceeff;
  --migration-target-text: #164977;
  --migration-target-border: #2b73b6;
  --selection-fill: #dceafa;
  --selection-text: #16395f;
  --selection-border: #4277a8;
  --attention-color: #795300;
  --surface-visualization: var(--neutral-0);
  --surface-blueprint: var(--neutral-50);
  --text-visualization: var(--neutral-900);
  --text-visualization-muted: #586a7b;
  --text-visualization-heading: #34576e;
  --border-visualization: #adbfcc;
  --grid-canvas: rgb(90 105 120 / 7%);
  --grid-visualization: rgb(90 105 120 / 7%);
  --shadow-color: #263545;
  --shadow-panel: 0 12px 32px #26354520;
  --shadow-popup: 0 4px 16px #26354526;
}
